function renderProducts(){let list=products.filter(p=>(activeCategory==="All"||p.category===activeCategory||(activeCategory==="Sheet Masks"&&p.size.toLowerCase().includes("sheet")))&&(`${p.name} ${p.brand} ${p.category} ${p.concerns.join(" ")}`).toLowerCase().includes($("#product-search").value.toLowerCase()));const sort=$("#sort-select").value;if(sort==="price-low")list.sort((a,b)=>a.price-b.price);if(sort==="price-high")list.sort((a,b)=>b.price-a.price);if(sort==="name")list.sort((a,b)=>a.name.localeCompare(b.name));$("#product-grid").innerHTML=list.length?list.map(p=>{const unavailable=p.stock===0;return `<article class="product-card"><div class="product-image-wrap"><img class="product-image" src="${p.image}" alt="Illustrative image for ${p.name}" loading="lazy"><span class="product-badge">${p.badge}</span><button class="wish-button ${wishlist.includes(p.id)?"active":""}" data-wish="${p.id}" aria-label="${wishlist.includes(p.id)?"Remove from":"Add to"} wishlist">${wishlist.includes(p.id)?"♥":"♡"}</button><button class="quick-view" data-quick="${p.id}">Quick look</button></div><div class="product-meta"><div class="product-brand">${p.brand}</div><h3 class="product-name">${p.name}</h3><div class="product-sub">${p.size} · ${p.tone}</div><div class="price-row"><span class="price">${money(p.price)}</span></div><div class="stock-note">${p.stock===undefined?"Checking availability…":unavailable?"Out of stock":`${p.stock} available`}</div><button class="add-button" data-add="${p.id}" ${unavailable?"disabled":""}>${unavailable?"Out of stock":"Add to bag +"}</button></div></article>`}).join(""):`<div class="no-results">No rituals found. Try another search.</div>`;$$("[data-add]").forEach(b=>b.onclick=()=>addCart(+b.dataset.add));$$("[data-wish]").forEach(b=>b.onclick=()=>toggleWish(+b.dataset.wish));$$("[data-quick]").forEach(b=>b.onclick=()=>quickView(+b.dataset.quick))}
function addCart(id,qty=1){const item=cart.find(i=>i.id===id);if(item)item.qty+=qty;else cart.push({id,qty});save();renderCart();toast(`${productById(id)?.name||"Item"} added to your sample bag`)}function toggleWish(id){wishlist=wishlist.includes(id)?wishlist.filter(x=>x!==id):[...wishlist,id];save();renderProducts();$("#wish-count").textContent=wishlist.length;toast(wishlist.includes(id)?"Saved to your wishlist":"Removed from your wishlist")}
